#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#define CAPACITY 4U

typedef struct { int items[CAPACITY]; size_t front; size_t count; } Queue;

static bool enqueue(Queue *q, int value)
{
    if (q == NULL || q->count >= CAPACITY) return false;
    size_t rear = (q->front + q->count) % CAPACITY;
    q->items[rear] = value;
    ++q->count;
    return true;
}

static bool dequeue(Queue *q, int *out)
{
    if (q == NULL || out == NULL || q->count == 0U) return false;
    *out = q->items[q->front];
    q->front = (q->front + 1U) % CAPACITY;
    --q->count;
    return true;
}

static bool peek(const Queue *q, int *out)
{
    if (q == NULL || out == NULL || q->count == 0U) return false;
    *out = q->items[q->front];
    return true;
}

int main(void)
{
    Queue q = {{0}, 0U, 0U};
    int value = 0;
    if (!enqueue(&q, 10) || !enqueue(&q, 20) || !enqueue(&q, 30)) return 1;
    if (!dequeue(&q, &value) || value != 10) return 2;
    if (!enqueue(&q, 40) || !enqueue(&q, 50)) return 3;
    if (enqueue(&q, 60)) return 4;
    if (!peek(&q, &value) || value != 20) return 5;
    while (dequeue(&q, &value)) printf("%d ", value);
    putchar('\n');
    return 0;
}

